<body>

<header>
  <div>
    <h1>Missing Names Resolver</h1>
    <p>Cumulative Sales Report &mdash; resolve names and account managers so the next report run is accurate.</p>
  </div>
  <button id="refreshBtn" onclick="loadState()">&#8635; Refresh</button>
</header>
<div id="statusBar">Loading&hellip;</div>

<div class="tabs">
  <button class="tab-btn active" data-tab="names" onclick="switchTab('names')">Missing Names <span class="count" id="countNames">0</span></button>
  <button class="tab-btn" data-tab="managers" onclick="switchTab('managers')">Missing Managers <span class="count" id="countManagers">0</span></button>
  <button class="tab-btn" data-tab="ignored" onclick="switchTab('ignored')">Ignored <span class="count" id="countIgnored">0</span></button>
</div>

<main>

  <div class="tab-panel active" id="panel-names">
    <div class="toolbar">
      <input id="searchBox" type="text" placeholder="Search a name&hellip;" oninput="renderNames()">
    </div>
    <div class="az-bar" id="azBar"></div>
    <div id="namesList"></div>
  </div>

  <div class="tab-panel" id="panel-managers">
    <div id="managersList"></div>
  </div>

  <div class="tab-panel" id="panel-ignored">
    <div id="ignoredList"></div>
  </div>

  <details class="activity">
    <summary>Recent activity (auto-matched &amp; manually resolved)</summary>
    <div id="activityLog"></div>
  </details>

</main>

<div class="toast" id="toast"></div>

<script>
const API_STATE  = 'resolve-names-state';
const API_ACTION = 'resolve-names-action';

let STATE = { missing_names: [], missing_managers: [], managers: [], sheets: [], ignored: [], auto_mapped_log: [], resolution_log: [] };
let activeLetter = 'ALL';
let currentTab = 'names';

function switchTab(tab) {
  currentTab = tab;
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  document.getElementById('panel-' + tab).classList.add('active');
}

function showToast(msg, isError) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.className = 'toast show' + (isError ? ' error' : '');
  setTimeout(() => { t.className = 'toast'; }, 2600);
}

function setStatus(msg) { document.getElementById('statusBar').textContent = msg; }

async function loadState() {
  setStatus('Loading current state…');
  try {
    const res = await fetch(API_STATE, { cache: 'no-store' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    STATE = await res.json();
    renderAll();
    setStatus('Last updated ' + (STATE.generated_at || '') + ' — ' +
      STATE.missing_names.length + ' missing name(s), ' +
      STATE.missing_managers.length + ' missing manager(s), ' +
      STATE.ignored.length + ' ignored.');
  } catch (e) {
    setStatus('Failed to load state: ' + e.message);
    showToast('Could not load state: ' + e.message, true);
  }
}

async function postAction(payload) {
  const res = await fetch(API_ACTION, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
  let data;
  try { data = await res.json(); } catch (e) { data = {}; }
  if (!res.ok || data.ok === false) {
    throw new Error(data.error || ('HTTP ' + res.status));
  }
  return data;
}

function renderAll() {
  document.getElementById('countNames').textContent = STATE.missing_names.length;
  document.getElementById('countManagers').textContent = STATE.missing_managers.length;
  document.getElementById('countIgnored').textContent = STATE.ignored.length;
  renderAzBar();
  renderNames();
  renderManagers();
  renderIgnored();
  renderActivity();
}

function renderAzBar() {
  const letters = new Set(STATE.missing_names.map(n => {
    const c = (n.raw || '').trim().charAt(0).toUpperCase();
    return /[A-Z]/.test(c) ? c : '#';
  }));
  const bar = document.getElementById('azBar');
  bar.innerHTML = '';
  const allBtn = document.createElement('button');
  allBtn.className = 'az-btn' + (activeLetter === 'ALL' ? ' active' : '');
  allBtn.textContent = 'All';
  allBtn.style.width = 'auto';
  allBtn.style.padding = '0 10px';
  allBtn.onclick = () => { activeLetter = 'ALL'; renderAzBar(); renderNames(); };
  bar.appendChild(allBtn);
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ#'.split('');
  alphabet.forEach(L => {
    const b = document.createElement('button');
    b.className = 'az-btn' + (activeLetter === L ? ' active' : '');
    b.textContent = L;
    const has = letters.has(L);
    b.disabled = !has;
    b.onclick = () => { activeLetter = L; renderAzBar(); renderNames(); };
    bar.appendChild(b);
  });
}

function matchesSearch(text) {
  const q = document.getElementById('searchBox').value.trim().toUpperCase();
  return !q || (text || '').toUpperCase().includes(q);
}

function renderNames() {
  const list = document.getElementById('namesList');
  list.innerHTML = '';
  let items = STATE.missing_names.slice();
  if (activeLetter !== 'ALL') {
    items = items.filter(n => {
      const c = (n.raw || '').trim().charAt(0).toUpperCase();
      const bucket = /[A-Z]/.test(c) ? c : '#';
      return bucket === activeLetter;
    });
  }
  items = items.filter(n => matchesSearch(n.raw));
  items.sort((a, b) => (a.raw || '').localeCompare(b.raw || ''));

  if (!items.length) {
    list.innerHTML = '<div class="empty-state">Nothing here — no missing names match this filter.</div>';
    return;
  }

  items.forEach(n => {
    const card = document.createElement('div');
    card.className = 'card';
    const formId = 'form-add-' + btoa(unescape(encodeURIComponent(n.raw))).replace(/[^a-zA-Z0-9]/g, '');
    const managerOptions = STATE.managers.map(m => '<option value="' + escapeHtml(m) + '">' + escapeHtml(m) + '</option>').join('');
    card.innerHTML = `
      <div class="card-row">
        <div>
          <div class="card-title">${escapeHtml(n.raw)}</div>
          <div class="card-sub">Not found in the cleaning map — pick a suggestion, add it as new, or skip it.</div>
        </div>
        <div class="btn-row">
          <button class="btn ghost" onclick="toggleAddForm('${formId}')">+ Add as new</button>
          <button class="btn warn" onclick="skipName('${escapeAttr(n.raw)}')">Skip</button>
        </div>
      </div>
      ${n.suggestions && n.suggestions.length ? `
        <div class="chip-row">
          ${n.suggestions.map(s => `<span class="chip" onclick="mapName('${escapeAttr(n.raw)}','${escapeAttr(s.name)}')">${escapeHtml(s.name)}<span class="score">${s.score}%</span></span>`).join('')}
        </div>` : ''}
      <div class="inline-form" id="${formId}">
        <input type="text" placeholder="Canonical name" value="${escapeAttr(n.raw.toUpperCase())}" data-role="canonical">
        <select data-role="manager"><option value="">(no manager yet)</option>${managerOptions}</select>
        <input type="text" placeholder="Sheet (optional)" data-role="sheet">
        <button class="btn primary" onclick="submitAddNew('${escapeAttr(n.raw)}', '${formId}')">Save</button>
        <button class="btn ghost" onclick="toggleAddForm('${formId}')">Cancel</button>
      </div>
    `;
    list.appendChild(card);
  });
}

function toggleAddForm(id) {
  document.querySelectorAll('.inline-form.open').forEach(f => { if (f.id !== id) f.classList.remove('open'); });
  document.getElementById(id).classList.toggle('open');
}

async function mapName(raw, canonical) {
  try {
    await postAction({ action: 'map_name', raw, canonical });
    showToast(`Mapped "${raw}" → "${canonical}"`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

async function submitAddNew(raw, formId) {
  const form = document.getElementById(formId);
  const canonical = form.querySelector('[data-role="canonical"]').value.trim();
  const manager = form.querySelector('[data-role="manager"]').value.trim();
  const sheet = form.querySelector('[data-role="sheet"]').value.trim();
  try {
    await postAction({ action: 'add_new', raw, canonical, manager, sheet });
    showToast(`Added "${raw}" as a new customer`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

async function skipName(raw) {
  try {
    await postAction({ action: 'skip', name: raw, scope: 'name' });
    showToast(`Skipped "${raw}" — moved to Ignored`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

function renderManagers() {
  const list = document.getElementById('managersList');
  list.innerHTML = '';
  const items = STATE.missing_managers.slice().sort();
  if (!items.length) {
    list.innerHTML = '<div class="empty-state">No customers are missing an account manager right now.</div>';
    return;
  }
  const managerOptions = STATE.managers.map(m => '<option value="' + escapeHtml(m) + '">' + escapeHtml(m) + '</option>').join('');
  items.forEach(name => {
    const card = document.createElement('div');
    card.className = 'card';
    const selId = 'mgr-sel-' + btoa(unescape(encodeURIComponent(name))).replace(/[^a-zA-Z0-9]/g, '');
    card.innerHTML = `
      <div class="card-row">
        <div>
          <div class="card-title">${escapeHtml(name)}</div>
          <div class="card-sub">Has sales but no account manager assigned.</div>
        </div>
        <div class="btn-row">
          <select id="${selId}-sel"><option value="">Pick a manager…</option>${managerOptions}</select>
          <input type="text" id="${selId}-sheet" placeholder="Sheet (optional)" style="background:var(--panel2);border:1px solid var(--border);color:var(--text);padding:6px 10px;border-radius:6px;font-size:12px;width:120px;">
          <button class="btn primary" onclick="assignManager('${escapeAttr(name)}','${selId}')">Assign</button>
          <button class="btn warn" onclick="skipManager('${escapeAttr(name)}')">Skip</button>
        </div>
      </div>
    `;
    list.appendChild(card);
  });
}

async function assignManager(name, selId) {
  const manager = document.getElementById(selId + '-sel').value;
  const sheet = document.getElementById(selId + '-sheet').value.trim();
  if (!manager) { showToast('Pick a manager first', true); return; }
  try {
    await postAction({ action: 'assign_manager', name, manager, sheet });
    showToast(`Assigned ${manager} to "${name}"`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

async function skipManager(name) {
  try {
    await postAction({ action: 'skip', name, scope: 'manager' });
    showToast(`Skipped manager assignment for "${name}" (will reappear next run)`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

function renderIgnored() {
  const list = document.getElementById('ignoredList');
  list.innerHTML = '';
  const items = STATE.ignored.slice();
  if (!items.length) {
    list.innerHTML = '<div class="empty-state">No names are ignored right now.</div>';
    return;
  }
  items.forEach(entry => {
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `
      <div class="card-row">
        <div>
          <div class="card-title">${escapeHtml(entry.canonical)}</div>
          <div class="card-sub">Ignored — self-mapped, and synced to the desktop app's ignore list.</div>
        </div>
        <div class="btn-row">
          <button class="btn danger" onclick="undoIgnore('${escapeAttr(entry.raw)}')">Undo</button>
        </div>
      </div>
    `;
    list.appendChild(card);
  });
}

async function undoIgnore(raw) {
  try {
    await postAction({ action: 'unskip', raw });
    showToast(`Un-ignored "${raw}" — back in Missing Names`);
    await loadState();
  } catch (e) { showToast('Failed: ' + e.message, true); }
}

function renderActivity() {
  const box = document.getElementById('activityLog');
  box.innerHTML = '';
  const auto = (STATE.auto_mapped_log || []).slice(0, 15).map(l => '<div class="log-line">' + escapeHtml(l) + '<span class="badge">auto</span></div>');
  const manual = (STATE.resolution_log || []).slice(0, 15).map(l => '<div class="log-line">' + escapeHtml(l) + '<span class="badge">manual</span></div>');
  const combined = auto.concat(manual);
  box.innerHTML = combined.length ? combined.join('') : '<div class="empty-state">No activity logged yet.</div>';
}

function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function escapeAttr(s) {
  return String(s == null ? '' : s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

loadState();
</script>

</body>
</html>
