const { execFileSync } = require('child_process');
const nodeProcess = require('process');
const PYTHON = "python";
const SCRIPT = "C:\\automation\\daily\\scripts\\resolve_api.py";

const item = $input.first().json;
const body = item.body || item;
const action = body.action;

function run(args) {
  const out = execFileSync(PYTHON, [SCRIPT, ...args], { encoding: 'utf-8', env: nodeProcess.env, maxBuffer: 1024 * 1024 * 20 });
  return JSON.parse(out);
}

let result;
try {
  if (action === 'map_name') {
    result = run(['map_name', '--raw', body.raw, '--canonical', body.canonical]);
  } else if (action === 'add_new') {
    const args = ['add_new', '--raw', body.raw];
    if (body.canonical) args.push('--canonical', body.canonical);
    if (body.manager) args.push('--manager', body.manager);
    if (body.sheet) args.push('--sheet', body.sheet);
    result = run(args);
  } else if (action === 'assign_manager') {
    const args = ['assign_manager', '--name', body.name, '--manager', body.manager];
    if (body.sheet) args.push('--sheet', body.sheet);
    result = run(args);
  } else if (action === 'skip') {
    result = run(['skip', '--name', body.name, '--scope', body.scope]);
  } else if (action === 'unskip') {
    result = run(['unskip', '--raw', body.raw]);
  } else if (action === 'undo_automap') {
    result = run(['undo_automap', '--raw', body.raw]);
  } else {
    result = { ok: false, error: 'Unknown action: ' + action };
  }
} catch (e) {
  result = { ok: false, error: e.message };
}

return [{ json: result }];
